        escape_json_string(event->source, escaped_src, sizeof(escaped_src));

        fprintf(logger->log_file,
            "{\"timestamp\":\"%s\",\"seq\":%lu,\"severity\":\"%s\",\"type\":\"%s\","
            "\"source\":\"%s\",\"user\":\"%s\",\"pid\":%d,\"message\":\"%s\"}\n",
            timestamp, event->sequence, severity_to_string(event->severity),
            event_type_to_string(event->type), escaped_src, event->user,
            event->pid, escaped_msg);
    } else {
        fprintf(logger->log_file,
            "[%s] [%s] [%s] [%s] [pid:%d] [user:%s] [seq:%lu] %s\n",
            timestamp, severity_to_string(event->severity),
            event_type_to_string(event->type), event->source,
            event->pid, event->user, event->sequence, event->message);
    }

    fflush(logger->log_file);
    pthread_mutex_unlock(&logger->file_mutex);
}

int security_logger_init(const char *log_filename, size_t max_file_size,
                         Severity min_severity, int enable_json) {
    if (g_initialized) return -1;

    memset(&g_logger, 0, sizeof(g_logger));

    strncpy(g_logger.log_filename, log_filename, sizeof(g_logger.log_filename) - 1);
    g_logger.max_file_size = max_file_size > 0 ? max_file_size : MAX_LOG_SIZE;
    g_logger.min_severity = min_severity;
    g_logger.enable_json = enable_json;
    g_logger.enable_syslog = 0;

    pthread_mutex_init(&g_logger.file_mutex, NULL);
    pthread_mutex_init(&g_logger.ring.mutex, NULL);

    g_logger.log_file = fopen(log_filename, "a");
    if (!g_logger.log_file) {
        return -1;
    }

    g_initialized = 1;

    SecurityEvent init_event = {0};
    init_event.timestamp = time(NULL);
    init_event.severity = SEV_INFO;
    init_event.type = EVT_SYSTEM;
    strncpy(init_event.source, "security_logger", sizeof(init_event.source) - 1);
    strncpy(init_event.user, "system", sizeof(init_event.user) - 1);
    init_event.pid = getpid();
    strncpy(init_event.message, "Security logger initialized", sizeof(init_event.message) - 1);
    init_event.sequence = 0;

    write_event_to_file(&g_logger, &init_event);

    return 0;
}

int security_log_event(Severity severity, EventType type, const char *source,
                       const char *user, const char *format, ...) {
    if (!g_initialized) return -1;
    if (severity < g_logger.min_severity) return 0;

    SecurityEvent event = {0};
    event.timestamp = time(NULL);
    event.severity = severity;
    event.type = type;
    event.pid = getpid();
    event.sequence = ++g_logger.total_events;

    strncpy(event.source, source ? source : "unknown", sizeof(event.source) - 1);
    strncpy(event.user, user ? user : "unknown", sizeof(event.user) - 1);

    va_list args;
    va_start(args, format);
    vsnprintf(event.message, sizeof(event.message), format, args);
    va_end(args);

    add_to_ring_buffer(&g_logger, &event);
    write_event_to_file(&g_logger, &event);

    if (severity >= SEV_CRITICAL) {
        fprintf(stderr, "[SECURITY ALERT] %s: %s\n",
                severity_to_string(severity), event.message);
    }

    return 0;
}

int security_log_auth(const char *user, const char *source_ip, int success,
                      const char *method) {
    Severity sev = success ? SEV_INFO : SEV_WARNING;
    EventType type = success ? EVT_AUTH : EVT_AUTH_FAIL;

    return security_log_event(sev, type, "auth",
        user, "Authentication %s for user '%s' from %s via %s",
        success ? "success" : "failure", user,
        source_ip ? source_ip : "unknown", method ? method : "unknown");
}

int security_log_file_access(const char *path, const char *user,
                             const char *operation, int success) {
    Severity sev = success ? SEV_INFO : SEV_WARNING;
    EventType type = success ? EVT_FILE_ACCESS : EVT_FILE_MODIFY;

    return security_log_event(sev, type, "file_access",
        user, "File %s: %s by user '%s' %s",
        operation ? operation : "access", path ? path : "unknown", user,
        success ? "succeeded" : "denied");
}

int security_log_network(const char *src_ip, int src_port,
                         const char *dst_ip, int dst_port,
                         const char *protocol, int blocked) {
    Severity sev = blocked ? SEV_WARNING : SEV_INFO;

    return security_log_event(sev, EVT_NETWORK, "network", "system",
        "Network connection %s: %s:%d -> %s:%d (%s) %s",
        blocked ? "blocked" : "allowed",
        src_ip ? src_ip : "unknown", src_port,
        dst_ip ? dst_ip : "unknown", dst_port,
        protocol ? protocol : "unknown",
        blocked ? "by firewall" : "established");
}

int security_log_privilege_escalation(const char *user, const char *target_user,
                                      const char *command, int success) {
    Severity sev = success ? SEV_WARNING : SEV_ERROR;

    return security_log_event(sev, EVT_PRIV_ESC, "privilege", user,
        "Privilege escalation attempt: '%s' -> '%s' executing '%s' %s",
        user, target_user ? target_user : "root",
        command ? command : "unknown",
        success ? "SUCCEEDED" : "DENIED");
}

typedef struct {
    Severity min_severity;
    EventType type_filter;
    int use_type_filter;
    const char *user_filter;
    const char *source_filter;
    int (*callback)(const SecurityEvent *event, void *user_data);
    void *user_data;
    int max_events;
} MonitorFilter;

static int matches_filter(const SecurityEvent *event, const MonitorFilter *filter) {
    if (event->severity < filter->min_severity) return 0;
    if (filter->use_type_filter && event->type != filter->type_filter) return 0;
    if (filter->user_filter && strcmp(event->user, filter->user_filter) != 0) return 0;
    if (filter->source_filter && strcmp(event->source, filter->source_filter) != 0) return 0;
    return 1;
}

int security_monitor_events(const MonitorFilter *filter, int duration_seconds) {
    if (!g_initialized) return -1;

    time_t start_time = time(NULL);
    int events_processed = 0;
    size_t last_count = g_logger.ring.count;

    while (duration_seconds < 0 || difftime(time(NULL), start_time) < duration_seconds) {
        pthread_mutex_lock(&g_logger.ring.mutex);

        if (g_logger.ring.count > last_count ||
            (g_logger.ring.count == RING_BUFFER_SIZE && last_count < RING_BUFFER_SIZE)) {
            size_t available = g_logger.ring.count - last_count;
            if (g_logger.ring.count == RING_BUFFER_SIZE && last_count == RING_BUFFER_SIZE) {
                available = 1;
            }

            for (size_t i = 0; i < available && events_processed < filter->max_events; i++) {
                size_t idx = (g_logger.ring.head + last_count + i) % RING_BUFFER_SIZE;
                SecurityEvent *event = &g_logger.ring.events[idx];

                if (matches_filter(event, filter)) {
                    if (filter->callback) {
                        filter->callback(event, filter->user_data);
                    } else {
                        char ts[64];
                        get_timestamp(ts, sizeof(ts), 0);
                        printf("[%s] [%s] [%s] %s: %s\n",
                               ts, severity_to_string(event->severity),
                               event_type_to_string(event->type),
                               event->source, event->message);
                    }
                    events_processed++;
                }
            }
            last_count = g_logger.ring.count;
        }

        pthread_mutex_unlock(&g_logger.ring.mutex);

        if (filter->max_events > 0 && events_processed >= filter->max_events) {
            break;
        }

        usleep(100000); /* 100ms */
    }

    return events_processed;
}

int security_get_recent_events(SecurityEvent *events, size_t max_events,
                               size_t *actual_count) {
    if (!g_initialized || !events || !actual_count) return -1;

    pthread_mutex_lock(&g_logger.ring.mutex);

    size_t count = g_logger.ring.count < max_events ? g_logger.ring.count : max_events;
    *actual_count = count;

    for (size_t i = 0; i < count; i++) {
        size_t idx = (g_logger.ring.head + g_logger.ring.count - count + i) % RING_BUFFER_SIZE;
        events[i] = g_logger.ring.events[idx];
    }

    pthread_mutex_unlock(&g_logger.ring.mutex);
    return 0;
}

